/* aesthetic tag v2.18.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ok: #15714b;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-ok-dark: #6fd2a8;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
    --ae-ok: var(--ae-ok-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
  --ae-ok: var(--ae-ok-dark);
}

.ae-icon {
width: 1.2em;
  height: 1.2em;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  vertical-align: -0.2em;
}

.ae-ok {
color: var(--ae-ok);
}

.ae-tag {
display: inline-block;
  font-family: var(--ae-font-mono);
  font-size: 11px;
  line-height: 1.6;
  letter-spacing: 0.14em;
  color: var(--ae-ink-muted);
  border: 1px solid var(--ae-line);
  padding: 0.1em 0.6em;
  vertical-align: 0.1em;
}

.ae-tag-bare {
border: 0;
  padding: 0;
}
